<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ev sahibi paneli</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1000px;margin:38px auto;padding:0 18px}.panel{background:white;padding:24px;border-radius:15px;margin:15px 0}.btn{background:#176b50;color:white;text-decoration:none;padding:11px 15px;border-radius:9px;font-weight:700}.muted{color:#68756c}</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="wrap"><h1>Ev sahibi paneli</h1><p>Merhaba, <?= e($vendor['business_name']) ?></p><section class="panel"><strong>Başvuru durumu: <?= e($vendor['status']) ?></strong><p class="muted"><?= $vendor['status']==='approved'?'İlanlarınızı yönetebilir ve yeni ilan ekleyebilirsiniz.':'Başvurunuz yönetici tarafından inceleniyor. Bu sırada ilanlarınızı taslak olarak hazırlayabilirsiniz.' ?></p><a class="btn" href="/vendor/bookings">Rezervasyonlar</a> <a class="btn" href="/vendor/properties">İlanlarım (<?= (int)$propertyCount ?>)</a> <a class="btn" href="/vendor/properties/new">Yeni ilan ekle</a></section><section class="panel"><h2>Banka ödeme bilgilerim</h2><p class="muted">Ödeme taleplerinizde kullanılacak banka hesabı bilgileri şifreli saklanır. IBAN bilgisi yönetim panelinde yalnızca yetkili yöneticilere gösterilir.</p><form method="post" action="/vendor/payout-profile" style="display:grid;gap:10px;max-width:620px"><?= csrf_field() ?><label>Banka adı<input name="payout_bank_name" maxlength="120" required value="<?= e($vendor['payout_bank_name']??'') ?>" style="display:block;width:100%;padding:11px;border:1px solid #dfe6e0;border-radius:8px;margin-top:5px"></label><label>Hesap sahibi<input name="payout_account_holder" maxlength="190" required value="<?= e($vendor['payout_account_holder']??'') ?>" style="display:block;width:100%;padding:11px;border:1px solid #dfe6e0;border-radius:8px;margin-top:5px"></label><label>IBAN<input name="payout_iban" maxlength="34" required value="<?= e($vendor['payout_iban']??'') ?>" placeholder="TR..." style="display:block;width:100%;padding:11px;border:1px solid #dfe6e0;border-radius:8px;margin-top:5px"></label><button class="btn" type="submit" style="border:0;cursor:pointer">Banka bilgilerini kaydet</button></form></section><section class="panel"><h2>Ödeme bakiyem</h2><?php if(!empty($vendorPayoutMessage)): ?><p class="muted" role="status"><?= e($vendorPayoutMessage) ?></p><?php endif; ?><?php if($vendor['status']!=='approved'): ?><p class="muted">Ödeme talebi oluşturmak için ev sahibi hesabınızın onaylanması gerekir.</p><?php elseif(!$vendorPayoutBalances): ?><p class="muted">Henüz ödemeye uygun, tahsil edilmiş ve konaklama tarihi tamamlanmış bakiye bulunmuyor.</p><?php else: ?><div style="display:grid;gap:12px"><?php foreach($vendorPayoutBalances as $balance): ?><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;border-bottom:1px solid #edf1ee;padding:8px 0"><strong><?= number_format((float)$balance['available_amount'],2,',','.') ?> <?= e($balance['currency']) ?></strong><form method="post" action="/vendor/payouts/request"><?= csrf_field() ?><input type="hidden" name="currency" value="<?= e($balance['currency']) ?>"><button class="btn" type="submit">Bu bakiye için ödeme talep et</button></form></div><?php endforeach; ?></div><?php endif; ?></section><section class="panel"><h2>Ödeme geçmişim</h2><?php if(empty($vendorPayouts)): ?><p class="muted">Henüz ödeme talebiniz bulunmuyor.</p><?php else: ?><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left;padding:9px">Talep</th><th style="text-align:left;padding:9px">Tutar</th><th style="text-align:left;padding:9px">Durum</th><th style="text-align:left;padding:9px">Referans</th></tr></thead><tbody><?php foreach($vendorPayouts as $payout): ?><tr><td style="padding:9px">#<?= (int)$payout['id'] ?><small style="display:block"><?= e(date('d.m.Y',strtotime($payout['requested_at']))) ?></small></td><td style="padding:9px"><?= number_format((float)$payout['amount'],2,',','.') ?> <?= e($payout['currency']) ?></td><td style="padding:9px"><?= e(['requested'=>'Talep edildi','processing'=>'İşleniyor','paid'=>'Ödendi','failed'=>'Başarısız','cancelled'=>'İptal edildi'][$payout['status']]??$payout['status']) ?></td><td style="padding:9px"><?= e($payout['payout_reference']??'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><p><a href="/">Siteyi görüntüle</a> · <a href="/account/bookings">Rezervasyonlar</a></p><?php require APP_ROOT . '/views/site/partials/logout-button.php'; ?></main></body></html>